def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def valid_amount(token: str) -> bool:
        return bool(token) and all("0" <= ch <= "9" for ch in token)

    for i, operation in enumerate(ops):
        tokens = operation.split(" ")
        if not tokens or any(token == "" for token in tokens):
            rejected.append(i)
            continue

        verb = tokens[0]
        action = None

        if verb == "open" and len(tokens) == 3:
            _, account, amount_token = tokens
            if valid_amount(amount_token):
                amount = int(amount_token)
                if account not in balances:
                    balances[account] = amount
                    action = ("open", account)

        elif verb == "deposit" and len(tokens) == 3:
            _, account, amount_token = tokens
            if valid_amount(amount_token):
                amount = int(amount_token)
                if amount > 0 and account in balances:
                    balances[account] += amount
                    action = ("balance", account, -amount)

        elif verb == "withdraw" and len(tokens) == 3:
            _, account, amount_token = tokens
            if valid_amount(amount_token):
                amount = int(amount_token)
                if (
                    amount > 0
                    and account in balances
                    and account not in frozen
                    and balances[account] >= amount
                ):
                    balances[account] -= amount
                    action = ("balance", account, amount)

        elif verb == "transfer" and len(tokens) == 4:
            _, source, destination, amount_token = tokens
            if valid_amount(amount_token):
                amount = int(amount_token)
                if (
                    amount > 0
                    and source != destination
                    and source in balances
                    and destination in balances
                    and source not in frozen
                    and balances[source] >= amount
                ):
                    balances[source] -= amount
                    balances[destination] += amount
                    action = ("transfer", source, destination, amount)

        elif verb == "freeze" and len(tokens) == 2:
            account = tokens[1]
            if account in balances and account not in frozen:
                frozen.add(account)
                action = ("freeze", account, False)

        elif verb == "unfreeze" and len(tokens) == 2:
            account = tokens[1]
            if account in balances and account in frozen:
                frozen.remove(account)
                action = ("freeze", account, True)

        elif verb == "undo" and len(tokens) == 1:
            if not history:
                rejected.append(i)
                continue

            action = history.pop()
            kind = action[0]
            if kind == "open":
                balances.pop(action[1])
                frozen.discard(action[1])
            elif kind == "balance":
                _, account, delta = action
                balances[account] += delta
            elif kind == "transfer":
                _, source, destination, amount = action
                balances[source] += amount
                balances[destination] -= amount
            elif kind == "freeze":
                _, account, was_frozen = action
                if was_frozen:
                    frozen.add(account)
                else:
                    frozen.discard(account)
            continue

        if action is None:
            rejected.append(i)
        else:
            history.append(action)

    return balances, rejected
